export function getApiVersionKey() {
  return ['{apiVersion}'] as const
}

export function getApiVersionAccountQueryKey(
  args: MaybeRefOrGetter<InferRequestType<(typeof client)[':apiVersion']['account']['$get']>>,
) {
  return [':apiVersion', '/:apiVersion/account', toValue(args)] as const
}

export function getApiVersionAccountQueryOptions(
  args: MaybeRefOrGetter<InferRequestType<(typeof client)[':apiVersion']['account']['$get']>>,
  options?: ClientRequestOptions,
) {
  return {
    queryKey: computed(() => getApiVersionAccountQueryKey(args)),
    queryFn({ signal }: QueryFunctionContext) {
      return parseResponse(
        client[':apiVersion'].account.$get(toValue(args), {
          ...options,
          init: { ...options?.init, signal },
        }),
      )
    },
  }
}

